CREATE TABLE customers (
    customer_id  integer PRIMARY KEY,
    full_name    text    NOT NULL,
    city         text    NOT NULL
);

CREATE TABLE orders (
    order_id     bigint  GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    customer_id  integer NOT NULL REFERENCES customers,
    status       text    NOT NULL,
    order_date   date    NOT NULL,
    amount       numeric(10,2) NOT NULL
);

INSERT INTO customers
SELECT g, 'Customer ' || g,
       (ARRAY['Mumbai','Delhi','Bengaluru','Chennai','Pune'])[g % 5 + 1]
  FROM generate_series(1, 5000) AS g;

INSERT INTO orders (customer_id, status, order_date, amount)
SELECT g % 5000 + 1,
       CASE WHEN g % 100 = 0 THEN 'pending' ELSE 'shipped' END,
       date '2026-01-01' + (g % 300),
       (g % 997) + 0.99
  FROM generate_series(1, 500000) AS g;

VACUUM ANALYZE customers, orders;

SET max_parallel_workers_per_gather = 0;
EXPLAIN SELECT * FROM orders WHERE customer_id = 42;
RESET max_parallel_workers_per_gather;

ALTER SYSTEM SET track_io_timing = on;
SELECT pg_reload_conf();
SHOW track_io_timing;

ALTER TABLE orders SET (autovacuum_enabled = off);

INSERT INTO orders (customer_id, status, order_date, amount)
SELECT g % 5000 + 1, 'cancelled', date '2026-11-01', 10.00
  FROM generate_series(1, 50000) AS g;

EXPLAIN (ANALYZE, BUFFERS)
SELECT count(*) FROM orders WHERE status = 'cancelled';

ANALYZE orders;

EXPLAIN (ANALYZE, BUFFERS)
SELECT count(*) FROM orders WHERE status = 'cancelled';

SHOW work_mem;

EXPLAIN (ANALYZE, BUFFERS)
SELECT * FROM orders ORDER BY amount DESC, order_id;

SET work_mem = '64MB';

EXPLAIN (ANALYZE, BUFFERS)
SELECT * FROM orders ORDER BY amount DESC, order_id;

RESET work_mem;

UPDATE orders SET amount = amount + 1 WHERE customer_id <= 500;

EXPLAIN (ANALYZE, BUFFERS)
SELECT count(*) FROM orders WHERE customer_id <= 500;

VACUUM orders;

EXPLAIN (ANALYZE, BUFFERS)
SELECT count(*) FROM orders WHERE customer_id <= 500;

ALTER TABLE orders RESET (autovacuum_enabled);

BEGIN;

EXPLAIN (ANALYZE, BUFFERS, WAL)
UPDATE orders SET status = 'shipped'
 WHERE customer_id = 101 AND status = 'pending';

ROLLBACK;

