# Create and connect to the practice database (db1, as your sudo user)
sudo -u postgres createdb shop
sudo -u postgres psql -d shop

# Estimated plan only, the statement does not run
EXPLAIN SELECT * FROM orders WHERE customer_id = 42;

# Run it and show actual time, rows, loops and buffers
EXPLAIN (ANALYZE, BUFFERS) SELECT * FROM orders WHERE customer_id = 42;

# Add I/O wait times for this session (superuser)
SET track_io_timing = on;

# Enable I/O timing for the whole cluster (reload is enough)
ALTER SYSTEM SET track_io_timing = on;
SELECT pg_reload_conf();

# Measure a data change without keeping it
BEGIN;
EXPLAIN (ANALYZE, BUFFERS, WAL) UPDATE orders SET status = 'shipped' WHERE customer_id = 101;
ROLLBACK;

# Plan a query that contains $1 (PostgreSQL 16+)
EXPLAIN (GENERIC_PLAN) SELECT * FROM orders WHERE customer_id = $1;

# Only row counts, less overhead
EXPLAIN (ANALYZE, TIMING OFF) SELECT count(*) FROM orders WHERE customer_id = 42;

# Show non-default planner settings, or machine-readable output
EXPLAIN (SETTINGS) SELECT * FROM orders WHERE customer_id = 42;
EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON) SELECT * FROM orders WHERE customer_id = 42;

# Fixes used in this part
CREATE INDEX orders_customer_id_idx ON orders (customer_id);
ANALYZE orders;
SET work_mem = '64MB';
VACUUM orders;

# Clean up the practice database (from the shell)
sudo -u postgres dropdb shop

